                w = max(c for _, c in norm) + 1
                comps.append({
                    "color": color,
                    "cells": cells,
                    "norm": norm,
                    "minr": minr,
                    "minc": minc,
                    "h": h,
                    "w": w,
                    "size": len(cells),
